def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i == len(line) or line[i] == ',':
                            fields.append(''.join(field))
                            if i < len(line):
                                i += 1  # Skip the comma
                            break
                        else:
                            # Closing quote not followed by comma or end
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < len(line):
                i += 1  # Skip the comma

    return fields

